import{Port,materials}from'../../core/index.js';import{portQuaternion}from'../../modeling/parts.js';import{THREE,mesh,box,annulus}from'./geometry.js';import{spec}from'./dimensions.js';
export function grove(host){const cfg=spec.grove,frame=new THREE.Group();frame.name='Original U011 red open-top HY2.0 receiving carrier';frame.position.fromArray(cfg.position);frame.quaternion.copy(portQuaternion('bottom'));host.body.add(frame);const red=materials.plastic(0xa92b3c,{roughness:.67}),metal=materials.metal(0xb7b49e),parts=[],add=(size,p,name,mat=red)=>{const o=box(frame,size,p,mat,'U011 Grove '+name);parts.push(o);return o;},walls=[];
 for(const x of[-4.65,4.65]){walls.push(add([.7,7.6,5.2],[x,-3.8,0],'actual side receiving wall'));walls.push(add([.65,7.6,.65],[Math.sign(x)*3.98,-3.8,2.25],'actual upper retaining rail'));}
 const floor=add([8.6,7.6,.6],[0,-3.8,-2.3],'physical socket floor rests on own PCB'),back=add([8.6,.7,4.6],[0,-7.25,.3],'deep dielectric contact stop'),latch=add([3.8,1.3,.5],[0,-4.7,2.25],'actual internal latch bridge'),contacts=[],returns=[],tails=[];
 for(let i=0;i<4;i++){const x=(i-1.5)*2,n=i+1;contacts.push(add([.42,5.8,.42],[x,-4,-.6],'retained square pin '+n,metal));returns.push(add([.42,.7,2.1],[x,-7.2,-1.45],'bent contact return '+n,metal));tails.push(add([.42,.42,1.9],[x,-7.4,-3.1],'real solder tail through PCB '+n,metal));}
 const port=host.add(new Port({id:'grove',label:'Original J1 · red HY2.0-4P',connector:'grove',position:cfg.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pinGrid:{cols:4,rows:1,pitch:2,center:[0,-.6],order:col=>col+1},pins:cfg.pins.map((name,i)=>({n:i+1,name})),meta:{role:'visual-connector',face:'bottom',physicalFamily:'HY2.0-4P receiving',numbering:'Own original schematic J1.1 SCL,J1.2 SDA,J1.3 VCC,J1.4 GND;literal rear legend.No automatic cable-wire or electrical routing.',scope:'Four real contacts/receiving carrier and cable mechanics only;no I2C,address,GPIO,voltage or firmware behavior.'}}));return{frame,parts,walls,floor,back,latch,contacts,returns,tails,port};}
export function io(host){const frame=new THREE.Group();frame.name='U011 actual P1 right-angle male2x5 contact assembly';host.body.add(frame);const black=materials.plastic(0x171c17),metal=materials.metal(0xbab49b),carrier=box(frame,[12.8,2.5,5.08],[0,10.5,2.67],black,'U011 P1 physical2x5 molded male pin carrier'),supports=[];for(const x of[-6,6])supports.push(box(frame,[.7,2.5,1.73],[x,10.5,-.735],black,'U011 inferred P1 carrier support to own PCB'));
 const contacts=[],legs=[],solder=[];for(let col=0;col<5;col++)for(let row=0;row<2;row++){const x=spec.io.columnX[col],z=spec.io.rowZ[row],y=spec.io.bendY[row],n=col*2+(row===1?1:2),contact=box(frame,[.64,15.7-y,.64],[x,(15.7+y)/2,z],metal,'U011 P1 actual solid male square contact '+n);contact.userData={role:'physical-contact',pin:n,row,column:col};contacts.push(contact);legs.push(box(frame,[.64,.64,z+2.7],[x,y,(z-2.7)/2],metal,'U011 P1 bent retaining through-board leg '+n));solder.push(mesh(frame,annulus(.72,.29,.2),metal,[x,y,-2.6],'U011 P1 actual solder retention collar '+n));}
 const names=['IO0','IO1','IO2','IO3','IO4','IO5','IO6','IO7','VCC','GND'];const port=host.add(new Port({id:'io',label:'Original P1 · 2x5 /2.54mm male',connector:spec.io.connector,position:spec.io.position,quaternion:portQuaternion('top'),hitSize:[14,1,5.6],pins:names.map((name,i)=>({n:i+1,name})),pinGrid:{cols:5,rows:2,pitch:2.54,center:[0,0],order:(col,row)=>col*2+(row===1?1:2)},meta:{role:'visual-connector',face:'top',physicalFamily:'Unshrouded right-angle2x5/2.54mm male header,recessed inside own white hood',source:'Own extio01 explicitly2x5@2.54mm,own05 solid pin view and own P1 Header5X2 schematic;not U011-B geometry.',pinMapping:'Own rear label viewed left-to-right:VCC/IO6/IO4/IO2/IO0,then GND/IO7/IO5/IO3/IO1. Original schematic P1.1..8=IO0..7,9=VCC,10=GND.',scope:'Actual ten pin mechanics and literal legend only;no GPIO state,readings,logic,ADC,PWM,protocol or electrical pin routing;no supplied attachment model.'}}));return{frame,carrier,supports,contacts,legs,solder,port};}
